def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The colored sequence in the top row defines vertical beams.
    beams = [(c, grid[0][c]) for c in range(w) if grid[0][c] != 0]
    for c, color in beams:
        for r in range(h):
            out[r][c] = color

    # Colored markers on the left/right edges send horizontal beams
    # inward to their matching vertical beam.
    beam_col = {color: c for c, color in beams}
    for r in range(h):
        if grid[r][0] != 0 and grid[r][0] in beam_col:
            color = grid[r][0]
            for c in range(0, beam_col[color] + 1):
                if c not in [bc for bc, _ in beams]:
                    out[r][c] = color
        if grid[r][w - 1] != 0 and grid[r][w - 1] in beam_col:
            color = grid[r][w - 1]
            for c in range(beam_col[color], w):
                if c not in [bc for bc, _ in beams]:
                    out[r][c] = color
    return out
