            color = grid[r][edge_c]
            if color not in top:
                continue
            c = top[color]
            for rr in range(min(r, 0), max(r, 0) + 1):
                out[rr][c] = color
            for cc in range(min(edge_c, c), max(edge_c, c) + 1):
                out[r][cc] = color
    return out
