def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    columns = {}
    for c, color in enumerate(grid[0]):
        if color:
            columns[color] = c

    # Border markers determine how far their matching vertical beam reaches.
    marker_rows = {}
    for r in range(h):
        for c in (0, w - 1):
            color = grid[r][c]
            if color in columns:
                marker_rows.setdefault(color, []).append((r, c))

    # Extend each top-row color vertically; matching border markers terminate it.
    for color, c in columns.items():
        end = max((r for r, _ in marker_rows.get(color, [])), default=h - 1)
        for r in range(end + 1):
            out[r][c] = color

    # Extend each matching border marker horizontally to its vertical beam.
    for color, markers in marker_rows.items():
        c = columns[color]
        for r, edge in markers:
            lo, hi = sorted((edge, c))
            for cc in range(lo, hi + 1):
                out[r][cc] = color

    return out
